questionvariables.text:
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Type a number in each box, not a letter.");
/* Design: matrix from the image of the unit square, given as coordinates. Source: adapted from SMP Book 5 (Metric), Chapter 14, Exercise B, question 2. No matrix is symmetric and A' differs from C', so the transpose and the swapped columns differ from the answer. */
mlist: [matrix([0,-2],[-3,3]),matrix([3,0],[5,-1]),matrix([5,-1],[-3,1]),matrix([-4,-3],[-2,-2]),matrix([-3,4],[3,0]),matrix([-1,1],[3,3]),matrix([1,0],[3,-2]),matrix([4,-4],[-1,-4]),matrix([4,-3],[4,0]),matrix([-4,-1],[-2,0])];
ix: 1+rand(10);
ta: mlist[ix];
a: ta[1,1]; b: ta[1,2]; c: ta[2,1]; d: ta[2,2];
Ap: [a,c]; Bp: [a+b,c+d]; Cp: [b,d];
/* diagnostics: images written as rows; columns in the wrong order; B' used for the second column */
dT: transpose(ta); dS: matrix([b,a],[d,c]); dB: matrix([a,a+b],[c,c+d]);
tr: matrix([Ap[1],Cp[1]],[Ap[2],Cp[2]]);
tw: ta+matrix([0,1],[0,0]);
